import{G as e,K as t,n,ot as r}from"./chunks/framework.C8_jer4d.js";var i=JSON.parse(`{"title":"Generate the documentation","description":"","frontmatter":{"title":"Generate the documentation","prev":{"text":"Lab 1: Overview"},"next":{"text":"Lab 2: Overview"}},"headers":[],"relativePath":"baw-lab/generate-docs/challenge.md","filePath":"baw-lab/generate-docs/challenge.md"}`),a={name:`baw-lab/generate-docs/challenge.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h2 id="📦-clue-1-the-archive" tabindex="-1">📦 Clue 1 - The Archive <a class="header-anchor" href="#📦-clue-1-the-archive" aria-label="Permalink to “📦 Clue 1 - The Archive”">​</a></h2><blockquote><p><em>&quot;Every application tells a story. It is all there, sealed inside a single export file — waiting for someone to ask the right question.&quot;</em></p></blockquote><h3 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h3><p>The <strong>Hiring Sample</strong> (<code>Hiring_Sample - Responsive_Hiring_Sample_v18001.twx</code>) is IBM&#39;s canonical demo application. It models a complete hiring process: candidates are submitted, screened by HR, interviewed by the hiring manager, and either approved or rejected — with notifications and escalations along the way.</p><hr><h3 id="🔍-challenge-1-—-confirm-the-twx-file-is-in-your-workspace" tabindex="-1">🔍 Challenge 1 — Confirm the TWX file is in your workspace <a class="header-anchor" href="#🔍-challenge-1-—-confirm-the-twx-file-is-in-your-workspace" aria-label="Permalink to “🔍 Challenge 1 — Confirm the TWX file is in your workspace”">​</a></h3><ol><li>In the Bob IDE Explorer panel, expand the <code>lab-1/</code> folder.</li><li>Confirm <code>Hiring_Sample - Responsive_Hiring_Sample_v18001.twx</code> is present. (Do <strong>not</strong> open, rename, or move it — Bob accesses it directly).</li></ol><div class="info custom-block"><p class="custom-block-title">✅ <strong>Checkpoint</strong></p><ul><li>The TWX file is visible in the Explorer inside the <code>lab-1/</code> folder.</li></ul></div><hr><h3 id="🤖-challenge-2-—-ask-bob-to-generate-the-documentation" tabindex="-1">🤖 Challenge 2 — Ask Bob to generate the documentation <a class="header-anchor" href="#🤖-challenge-2-—-ask-bob-to-generate-the-documentation" aria-label="Permalink to “🤖 Challenge 2 — Ask Bob to generate the documentation”">​</a></h3><ol><li><p>Open the Bob Chat Panel with <strong>Option + Cmd + B</strong> (macOS) or <strong>Ctrl + Alt + B</strong> (Windows/Linux), or click the <strong>Bob icon</strong> beside the navigation bar.</p></li><li><p>Start a <strong>new chat</strong> by clicking the <strong>+</strong> (New Chat) icon at the top of the panel.</p></li><li><p>Click the <strong>+</strong> at the bottom left of the chat input, select <strong>IBM BAW Author</strong> under <strong>Modes</strong>, and enter the following prompt:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Help me to generate the documentation for my Hiring Sample application. </span></span>
<span class="line"><span>Store the results in docs/lab1-output/</span></span></code></pre></div></li><li><p>Press <strong>Enter</strong> and click <strong>Approve skill tools for task</strong> when prompted.</p></li><li><p>Bob asks which audience to target. Choose one of the four options:</p><table tabindex="0"><thead><tr><th>Option</th><th>Best for</th></tr></thead><tbody><tr><td><strong>Executive summary</strong></td><td>Stakeholders who need business value, no technical detail</td></tr><tr><td><strong>Knowledge transfer (KT)</strong></td><td>Developers onboarding to the application</td></tr><tr><td><strong>Partner handoff</strong></td><td>External teams receiving the application with improvement notes</td></tr><tr><td><strong>Technical reference</strong></td><td>A complete technical record of every process, service, BO, and coach view</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 <strong>Tip:</strong> Choose <strong>Technical reference</strong> to see the most complete output for this lab.</p></div><div class="info custom-block"><p class="custom-block-title">👥 <strong>Audience Profile Contrast</strong></p><ul><li><strong>Executive Summary:</strong> Condensed 1–2 page overview highlighting business purpose, high-level SLA milestones, and decision routing without technical code structures.</li><li><strong>Technical Reference:</strong> Comprehensive engineering catalog documenting XML IDs, variable types, script task snippets, Ajax services, and Coach View bindings.</li></ul></div></li><li><p>Approve each operation individually as Bob unpacks the archive, inspects artifact layers, and generates the Markdown documentation.</p></li></ol><div class="warning custom-block"><p class="custom-block-title">⚠️ <strong>Why multiple approvals appear</strong></p><p>A BAW <code>.twx</code> export is a multi-layered ZIP archive containing dozens of specialized XML and JSON artifacts (BPD flow models, Client-Side Human Services, Coach View layout trees, <code>twClass</code> business object definitions, and Ajax service flows). Bob works through each artifact layer in turn — which is why you see several approval requests in sequence. Read each one before approving it.</p></div><div class="info custom-block"><p class="custom-block-title">✅ <strong>Checkpoint</strong></p><ul><li>Bob confirms the documentation file has been written and displays a plain-language summary in the chat. The output path — for example <code>docs/lab1-output/Hiring_Sample-documentation.md</code> — is shown in the response.</li></ul></div><hr><h3 id="📖-challenge-3-—-review-the-generated-documentation" tabindex="-1">📖 Challenge 3 — Review the generated documentation <a class="header-anchor" href="#📖-challenge-3-—-review-the-generated-documentation" aria-label="Permalink to “📖 Challenge 3 — Review the generated documentation”">​</a></h3><ol><li>In the Explorer, navigate to <code>docs/lab1-output/</code> and open the generated <code>.md</code> file.</li><li>Scroll through the document and locate: <ul><li>The <strong>Application Overview</strong> section at the top</li><li>A <strong>Mermaid process flow diagram</strong> showing the hiring steps as a flowchart</li><li>The <strong>Business Objects</strong> section listing the data structures used by the process</li></ul></li><li>Open the Markdown preview to see the diagrams rendered: right-click the editor tab and choose <strong>Open Preview</strong>. Alternatively, click once inside the document text in the editor, so the editor has focus rather than the Explorer, and press <strong>Cmd + Shift + V</strong> (macOS) / <strong>Ctrl + Shift + V</strong> (Windows/Linux).</li><li>Confirm the Mermaid diagrams render as visual flowcharts in the preview pane.</li></ol><div class="info custom-block"><p class="custom-block-title">✅ <strong>Final Checkpoint</strong></p><ul><li>The generated documentation file exists under <code>docs/lab1-output/</code>, contains at least one process flow diagram, a Business Objects section, and all content renders correctly in the Markdown preview.</li></ul></div>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};